// Generate the emoji tables both surfaces read, from one source.
//
// Source: gemoji's `db/emoji.json` (https://github.com/github/gemoji). Its
// `aliases` are the shortcodes, and its file order and `category` give the
// picker its grouping and ordering. Run this by hand and commit the output;
// it is never run in CI.
//
//   node web/scripts/gen-emoji.mjs [path-to-emoji.json]
//
// With no argument it fetches the gemoji JSON over the network. With a path it
// reads that file instead, so a regeneration can be reproduced offline from a
// copy. It writes two generated files that must agree, which a Rust test
// enforces:
//
//   web/src/emoji-table.ts      alias -> char, plus the picker catalog
//   zorp-agent/src/emoji_table.rs   alias -> char, for the terminal's expand
//
// Skin-tone and ZWJ sequences are entries in the source, not logic here.

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const GEMOJI_URL =
  "https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json";

const here = dirname(fileURLToPath(import.meta.url));
const webSrc = join(here, "..", "src");
const agentSrc = join(here, "..", "..", "zorp-agent", "src");

async function load() {
  const arg = process.argv[2];
  if (arg) {
    return JSON.parse(await readFile(arg, "utf8"));
  }
  const res = await fetch(GEMOJI_URL);
  if (!res.ok) {
    throw new Error(`fetch ${GEMOJI_URL}: ${res.status}`);
  }
  return res.json();
}

// A shortcode is a lookup key and must match the one the expanders scan for,
// so anything outside the key charset is dropped rather than silently
// producing a name no `:…:` can ever reference.
const KEY = /^[a-z0-9_+-]+$/;

function build(entries) {
  // alias -> char. A later entry never overwrites an earlier one, so the
  // order in the source decides a collision, which is the source's own call.
  const shortcodes = new Map();
  const catalog = [];
  for (const e of entries) {
    const char = e.emoji;
    const aliases = (e.aliases || []).filter((a) => KEY.test(a));
    if (aliases.length === 0 || typeof char !== "string" || char.length === 0) {
      continue;
    }
    for (const alias of aliases) {
      if (!shortcodes.has(alias)) {
        shortcodes.set(alias, char);
      }
    }
    const keywords = Array.from(
      new Set([...aliases, ...(e.tags || []), ...(e.description || "").split(/\s+/)]),
    )
      .filter((k) => k && KEY.test(k.toLowerCase()))
      .map((k) => k.toLowerCase());
    catalog.push({
      char,
      name: aliases[0],
      category: e.category || "Other",
      keywords: Array.from(new Set(keywords)),
    });
  }
  return { shortcodes, catalog };
}

function tsFile({ shortcodes, catalog }) {
  const pairs = [...shortcodes.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1));
  const codes = pairs
    .map(([alias, char]) => `  ${JSON.stringify(alias)}: ${JSON.stringify(char)},`)
    .join("\n");
  const cat = catalog
    .map(
      (c) =>
        `  { char: ${JSON.stringify(c.char)}, name: ${JSON.stringify(c.name)}, category: ${JSON.stringify(c.category)}, keywords: ${JSON.stringify(c.keywords.join(" "))} },`,
    )
    .join("\n");
  return `// GENERATED by web/scripts/gen-emoji.mjs from gemoji db/emoji.json. Do not edit.
//
// \`EMOJI_SHORTCODES\` maps a shortcode to its character. \`EMOJI_CATALOG\` is
// the ordered list the picker draws, each with the keywords search matches on.
// The Rust side (zorp-agent/src/emoji_table.rs) is generated from the same
// source and a test asserts the alias -> char maps agree.

export interface EmojiEntry {
  char: string;
  name: string;
  category: string;
  keywords: string;
}

export const EMOJI_SHORTCODES: Record<string, string> = {
${codes}
};

export const EMOJI_CATALOG: readonly EmojiEntry[] = [
${cat}
];
`;
}

function rsFile({ shortcodes }) {
  const pairs = [...shortcodes.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1));
  const rows = pairs
    .map(([alias, char]) => `    (${rustStr(alias)}, ${rustStr(char)}),`)
    .join("\n");
  return `// GENERATED by web/scripts/gen-emoji.mjs from gemoji db/emoji.json. Do not edit.
//
// A shortcode mapped to its character, sorted by shortcode. The browser side
// (web/src/emoji-table.ts) is generated from the same source and
// zorp-agent/tests/emoji_drift.rs asserts the two agree.

/// \`(shortcode, character)\`, sorted by shortcode so a lookup can binary search.
pub static SHORTCODES: &[(&str, &str)] = &[
${rows}
];
`;
}

// Aliases are `[a-z0-9_+-]` and the characters are emoji, neither of which
// contains a backslash or a quote, but escape anyway so a future source change
// cannot emit a broken literal.
function rustStr(s) {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

const entries = await load();
const built = build(entries);
await writeFile(join(webSrc, "emoji-table.ts"), tsFile(built));
await writeFile(join(agentSrc, "emoji_table.rs"), rsFile(built));
console.error(
  `wrote ${built.shortcodes.size} shortcodes and ${built.catalog.length} catalog entries`,
);
